select 'DRE da janela: fatos = ' || (select count(*) from fato_financeiro f join campo_extraido ce on ce.id=f.campo_extraido_id join documento_versao dv on dv.id=ce.documento_versao_id where dv.nome_original='janela.pdf') || ' de ' || (select count(*) from campo_extraido ce join documento_versao dv on dv.id=ce.documento_versao_id where dv.nome_original='janela.pdf') || ' linhas' as dre;
select 'fatos de origem documento com entidade diferente da do documento: ' || count(*) as velhos from fato_financeiro f join documento_versao dv on dv.id=f.documento_versao_id join documento d on d.id=dv.documento_id where f.entidade_origem='documento' and f.entidade_id is distinct from d.entidade_id;
